import numpy as np, itertools, sys
def unit(v): v=np.array(v,float); return v/np.linalg.norm(v)
def tetra_dirs(bond_dir, ref):
    d=unit(bond_dir); r=unit(ref - np.dot(ref,d)*d); s=np.cross(d,r); out=[]
    for ang in [0,120,240]:
        a=np.radians(ang)
        out.append(unit(-d*np.cos(np.radians(70.53)) + np.sin(np.radians(70.53))*(r*np.cos(a)+s*np.sin(a))))
    return out
def build(rn, r2, tz, tn, hz, hn, rot):
