    z=np.array([0,0,1.])
    for i in range(4):
        a=cu[i]; b=cu[(i+1)%4]
        M=(a+b)/2; n=unit(M); u=unit(b-a)
        sgn = 1 if i%2==0 else -1
        Ca=M+rn*n - 1.25*u; Cb=M+rn*n + 1.25*u
        C2=M+(rn+r2)*n + 0.5*z*sgn
        for C in (Ca,C2,Cb): add('C',C)
